fn find_root(parent: Map[Str, Str], x: Str) -> Str {
  let p = parent.get(x).unwrap_or(x)
  if p == x {
    return x
  }
  return find_root(parent, p)
}

pub fn groups(pairs: List[List[Str]]) -> List[List[Str]] {
  var parent: Map[Str, Str] = Map {}
  for pair in pairs {
    let ra = find_root(parent, pair.get_or(0, ""))
    let rb = find_root(parent, pair.get_or(1, ""))
    if ra != rb {
      parent = parent.set(ra, rb)
    }
  }
  let final_parent = parent
  let nodes = pairs.flatten().unique().sort()
  let by_root = nodes.group_by(fn(n) => find_root(final_parent, n))
  let members = by_root.values().map(fn(g) => g.sort())
  return members.sort_by(fn(g) => g.get_or(0, ""))
}
